content:
Your showcase-api has been deployed.

1. Get the application URL:
   kubectl -n {{ .Release.Namespace }} port-forward svc/{{ include "showcase.fullname" . }} 8080:{{ .Values.service.port }}

   then open http://localhost:8080

2. Check health:
   curl http://localhost:8080/healthz
   curl http://localhost:8080/metrics
{{- if .Values.ingress.enabled }}

3. Ingress host: {{ (index .Values.ingress.hosts 0).host }}
{{- end }}

{{- define "showcase.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "showcase.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{- define "showcase.selectorLabels" -}}
app.kubernetes.io/name: {{ include "showcase.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end }}

{{- define "showcase.image" -}}
{{- $tag := default .Chart.AppVersion .Values.image.tag }}
{{- printf "%s:%s" .Values.image.repository $tag }}
{{- end }}

apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "showcase.fullname" . }}
  labels:
    {{- include "showcase.selectorLabels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "showcase.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      annotations:
        {{- toYaml .Values.podAnnotations | nindent 8 }}
      labels:
        {{- include "showcase.selectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "showcase.fullname" . }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      containers:
        - name: api
          image: {{ include "showcase.image" . }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          ports:
            - name: http
              containerPort: 8000
              protocol: TCP
          env:
            {{- range $k, $v := .Values.env }}
            - name: {{ $k }}
              value: {{ $v | quote }}
            {{- end }}
          livenessProbe:
            httpGet:
              path: /healthz
              port: http
            initialDelaySeconds: 5
            periodSeconds: 10
          readinessProbe:
            httpGet:
              path: /readyz
              port: http
            initialDelaySeconds: 3
            periodSeconds: 5
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          securityContext:
            {{- toYaml .Values.securityContext | nindent 12 }}
          volumeMounts:
            - name: tmp
              mountPath: /tmp
      volumes:
        - name: tmp
          emptyDir: {}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

{{- if .Values.autoscaling.enabled }}
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: {{ include "showcase.fullname" . }}
  labels:
    {{- include "showcase.selectorLabels" . | nindent 4 }}
spec:
  scaleTargetRef:
    apiVersion: apps/v1
    kind: Deployment
    name: {{ include "showcase.fullname" . }}
  minReplicas: {{ .Values.autoscaling.minReplicas }}
  maxReplicas: {{ .Values.autoscaling.maxReplicas }}
  metrics:
    - type: Resource
      resource:
        name: cpu
        target:
          type: Utilization
          averageUtilization: {{ .Values.autoscaling.targetCPUUtilizationPercentage }}
{{- end }}

{{- if .Values.ingress.enabled -}}
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: {{ include "showcase.fullname" . }}
  labels:
    {{- include "showcase.selectorLabels" . | nindent 4 }}
  {{- with .Values.ingress.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  ingressClassName: {{ .Values.ingress.className }}
  rules:
    {{- range .Values.ingress.hosts }}
    - host: {{ .host | quote }}
      http:
        paths:
          {{- range .paths }}
          - path: {{ .path }}
            pathType: {{ .pathType }}
            backend:
              service:
                name: {{ include "showcase.fullname" $ }}
                port:
                  number: {{ $.Values.service.port }}
          {{- end }}
    {{- end }}
{{- end }}

apiVersion: v1
kind: Service
metadata:
  name: {{ include "showcase.fullname" . }}
  labels:
    {{- include "showcase.selectorLabels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: http
      protocol: TCP
      name: http
  selector:
    {{- include "showcase.selectorLabels" . | nindent 4 }}

{{- if .Values.serviceAccount.create -}}
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ include "showcase.fullname" . }}
  labels:
    {{- include "showcase.selectorLabels" . | nindent 4 }}
  {{- with .Values.serviceAccount.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
automountServiceAccountToken: false
{{- end }}

{
  "uid": "showcase-api",
  "title": "Showcase API — Golden Signals",
  "tags": ["showcase", "devops"],
  "timezone": "browser",
  "schemaVersion": 39,
  "refresh": "10s",
  "time": { "from": "now-30m", "to": "now" },
  "panels": [
    {
      "id": 1,
      "type": "timeseries",
      "title": "Request rate (QPS)",
      "gridPos": { "h": 8, "w": 12, "x": 0, "y": 0 },
      "targets": [
        {
          "expr": "sum(rate(http_requests_total[1m])) by (endpoint)",
          "legendFormat": "{{endpoint}}"
        }
      ],
      "fieldConfig": {
        "defaults": { "unit": "reqps" },
        "overrides": []
      }
    },
    {
      "id": 2,
      "type": "timeseries",
      "title": "5xx error rate",
      "gridPos": { "h": 8, "w": 12, "x": 12, "y": 0 },
      "targets": [
        {
          "expr": "sum(rate(http_requests_total{http_status=~\"5..\"}[1m])) / sum(rate(http_requests_total[1m]))",
          "legendFormat": "error ratio"
        }
      ],
      "fieldConfig": {
        "defaults": { "unit": "percentunit", "max": 1 },
        "overrides": []
      }
    },
    {
      "id": 3,
      "type": "timeseries",
      "title": "Latency (p50 / p95 / p99)",
      "gridPos": { "h": 8, "w": 12, "x": 0, "y": 8 },
      "targets": [
        {
          "expr": "histogram_quantile(0.50, sum(rate(http_request_duration_seconds_bucket[1m])) by (le))",
          "legendFormat": "p50"
        },
        {
          "expr": "histogram_quantile(0.95, sum(rate(http_request_duration_seconds_bucket[1m])) by (le))",
          "legendFormat": "p95"
        },
        {
          "expr": "histogram_quantile(0.99, sum(rate(http_request_duration_seconds_bucket[1m])) by (le))",
          "legendFormat": "p99"
        }
      ],
      "fieldConfig": {
        "defaults": { "unit": "s" },
        "overrides": []
      }
    },
    {
      "id": 4,
      "type": "timeseries",
      "title": "Requests in flight",
      "gridPos": { "h": 8, "w": 12, "x": 12, "y": 8 },
      "targets": [
        { "expr": "http_requests_in_flight", "legendFormat": "in-flight" }
      ],
      "fieldConfig": {
        "defaults": { "unit": "short" },
        "overrides": []
      }
    }
  ]
}

provider "kubernetes" {
  config_path = var.kubeconfig_path
}

provider "helm" {
  kubernetes {
    config_path = var.kubeconfig_path
  }
}

locals {
  common_labels = {
    "app.kubernetes.io/part-of" = "devops-showcase"
    "app.kubernetes.io/managed-by" = "terraform"
    environment                  = var.environment
  }
}

# ---- Namespaces -----------------------------------------------------------
resource "kubernetes_namespace_v1" "apps" {
  metadata {
    name   = "showcase-${var.environment}"
    labels = local.common_labels
  }
}

resource "kubernetes_namespace_v1" "monitoring" {
  count = var.install_monitoring ? 1 : 0
  metadata {
    name   = "monitoring"
    labels = local.common_labels
  }
}

# ---- Ingress controller (kind uses the bare-metal flavor with hostPort) ---
resource "helm_release" "ingress_nginx" {
  count      = var.install_ingress ? 1 : 0
  name       = "ingress-nginx"
  repository = "https://kubernetes.github.io/ingress-nginx"
  chart      = "ingress-nginx"
  version    = "4.11.1"
  namespace  = "ingress-nginx"
  create_namespace = true

  set {
    name  = "controller.service.type"
    value = "NodePort"
  }
  set {
    name  = "controller.hostNetwork.enabled"
    value = "true"
  }
  set {
    name  = "controller.hostPort.enabled"
    value = "true"
  }
}

# ---- Monitoring stack (delegated to a reusable module) --------------------
module "monitoring" {
  source   = "./modules/monitoring"
  count    = var.install_monitoring ? 1 : 0

  namespace           = kubernetes_namespace_v1.monitoring[0].metadata[0].name
  grafana_password    = var.grafana_admin_password
  environment         = var.environment

  depends_on = [helm_release.ingress_nginx]
}

variable "namespace" {
  type = string
}
variable "grafana_password" {
  type      = string
  sensitive = true
}
variable "environment" {
  type = string
}

terraform {
  required_providers {
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.13"
    }
  }
}

# kube-prometheus-stack bundles Prometheus, Grafana, Alertmanager, node-exporter
# and a set of default dashboards/alerts. Pinning the chart version is what
# makes upgrades reviewable and reproducible.
resource "helm_release" "kube_prometheus_stack" {
  name             = "kube-prometheus-stack"
  repository       = "https://prometheus-community.github.io/helm-charts"
  chart            = "kube-prometheus-stack"
  version          = "61.3.2"
  namespace        = var.namespace
  create_namespace = false
  timeout          = 600

  values = [
    yamlencode({
      grafana = {
        adminPassword = var.grafana_password
        service = { type = "ClusterIP" }
        sidecar = { dashboards = { enabled = true }, datasources = { enabled = true } }
      }
      prometheus = {
        prometheusSpec = {
          retention = "7d"
          additionalScrapeConfigs = []
        }
      }
      alertmanager = {
        config = {
          receivers = [{ name = "null" }]
          route    = { receiver = "null" }
        }
      }
      commonLabels = { environment = var.environment }
    })
  ]
}

output "apps_namespace" {
  description = "Namespace where the showcase app is deployed."
  value       = kubernetes_namespace_v1.apps.metadata[0].name
}

output "grafana_url" {
  description = "How to reach Grafana locally (port-forward helper in Makefile)."
  value       = var.install_monitoring ? "make grafana  # http://localhost:3000" : "monitoring disabled"
}

output "prometheus_url" {
  description = "How to reach Prometheus locally."
  value       = var.install_monitoring ? "make prometheus  # http://localhost:9090" : "monitoring disabled"
}

variable "kubeconfig_path" {
  description = "Path to the kubeconfig used to talk to the target cluster."
  type        = string
  default     = "~/.kube/config"
}

variable "environment" {
  description = "Logical environment name, used for naming and labels."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of dev, staging, prod."
  }
}

variable "install_monitoring" {
  description = "Whether to install the kube-prometheus-stack via Helm."
  type        = bool
  default     = true
}

variable "install_ingress" {
  description = "Whether to install ingress-nginx (the bare-metal/kind flavor)."
  type        = bool
  default     = true
}

variable "grafana_admin_password" {
  description = "Admin password for Grafana. Override via TF_VAR_ in CI; never commit a real one."
  type        = string
  sensitive   = true
  default     = "admin"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.30"
    }
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.13"
    }
  }

  # For a real team, switch this to an S3/GCS backend with state locking:
  # backend "s3" {
  #   bucket         = "company-terraform-state"
  #   key            = "showcase/k8s.tfstate"
  #   region         = "ap-guangzhou"
  #   dynamodb_table = "terraform-lock"
  #   encrypt        = true
  # }
}
